INSERT INTO ong.research_batches (sha256, as_of, snapshot) VALUES ('1d827e2576ada7774fbcd64220e2aebb75c16668543c70ce22fbb570073c20a9', '2026-10-22', '{"meta": {"title": "Mapa inicial de cooperación europea para ONG en Cusco", "version": "0.1", "as_of": "2026-10-22", "timezone": "America/Lima", "scope": "Europa ampliada de trabajo + UE; revisión inicial desigual, no exhaustiva", "organization_stage": "por_constituir", "currency_policy": "Monedas originales, sin conversión de tipo de cambio"}, "sources": [{"id": "S01", "title": "Chequia: convocatoria completa 2027", "url": "https://mzv.gov.cz/lima/es/comercio_y_economia/convocatoria_2027_para_proyectos_de_1.html", "checked_on": "2026-10-22", "level": "primaria", "access": "contenido_consultado", "note": "Cierre, monto, registro y exclusiones explícitos. Publicada 15/09/2026."}, {"id": "S02", "title": "Suiza: proyectos culturales", "url": "https://www.schweiz-peru.eda.admin.ch/es/proyectos-culturales", "checked_on": "2026-10-22", "level": "primaria", "access": "contenido_consultado", "note": "Página de 28/09/2026; regla anual de recepción, vínculo suizo y monto."}, {"id": "S03", "title": "Alemania: cooperación para el desarrollo", "url": "https://lima.diplo.de/pe-es/willkommen/07-entwicklungszusammenarbeit", "checked_on": "2026-10-22", "level": "primaria", "access": "contenido_consultado", "note": "Coordinación bilateral; GIZ y KfW. No acredita un fondo local abierto."}, {"id": "S04", "title": "IKI Small Grants 2026", "url": "https://www.international-climate-initiative.com/en/find-funding/small-grants/small-grants-2026/", "checked_on": "2026-10-22", "level": "primaria", "access": "extracto_buscador", "note": "Anuncio oficial recuperado por buscador; apertura futura condicionada; reapertura directa falló."}, {"id": "S05", "title": "IKI Medium Grants 2026", "url": "https://www.international-climate-initiative.com/en/find-funding/medium-grants/medium-grants-2026/", "checked_on": "2026-10-22", "level": "primaria", "access